// Canonical Draft-07 schemas; JSON artifacts are generated by the CLI.
const str = { type: 'string', minLength: 1 }
const strings = { type: 'array', items: str, uniqueItems: true }
const list = (items, minItems = 0) => ({ type: 'array', items, minItems })
const enumeration = (...values) => ({ enum: values })
const nullable = (type) => ({ anyOf: [type, { type: 'null' }] })
const object = (properties) => ({ type: 'object', additionalProperties: false, required: Object.keys(properties), properties })
const date = { type: 'string', format: 'date-time' }
const digest = { type: 'string', pattern: '^[a-f0-9]{64}$' }
const refs = { ...strings, minItems: 1 }
export const families = ['jira', 'smartshark', 'slack', 'disco', 'wikimedia', 'japanese_oss', 'figma', 'apache_mail']
export const pairwise = ['SAME_WORK', 'RELATED_DIFFERENT_WORK', 'UNRELATED', 'UNCERTAIN']
export const structural = ['PARENT_OF', 'CHILD_OF', 'CONTRIBUTES_TO', 'IMPLEMENTS', 'VERIFIES', 'REVIEWS', 'DEPENDS_ON', 'BLOCKS', 'PRECEDES', 'FOLLOWS', 'DUPLICATE_OF', 'EVIDENCE_FOR', 'CONTRADICTS', 'SUPERSEDES', 'SPLIT_FROM', 'MERGED_INTO', 'UNKNOWN_RELATION']
export const levels = ['L0', 'L1', 'L2', 'L3', 'UNKNOWN_LEVEL', 'ONTOLOGY_MISMATCH']
export const confidence = enumeration('low', 'medium', 'high')
export const sourceSchema = object({
  schema_version: { const: 'external-source-record/v1' }, source_id: str,
  provider: str, dataset: str, project: str, source_type: str, external_id: str,
  source_url: { type: 'string', format: 'uri' }, timestamp: nullable(date),
  author_anonymized: str, title: { type: 'string' }, content: str,
  explicit_refs: strings, structured_relations: list(object({ type: str, target_ref: str })),
  metadata: { ...object({ artifact_only: { type: 'boolean' }, context_ref: str }), properties: {
    artifact_only: { type: 'boolean' }, context_ref: str, original_timestamp: { type: 'string' } } }, license: str,
  provenance: object({ raw_hash: digest, content_hash: digest, retrieved_at: date, raw_reference: str }),
  sanitization: object({ boundary: { const: 'public-source-sandbox/v1' }, version: { const: '1' }, trust: { const: 'untrusted' } }),
})
export const atomSchema = object({
  atom_id: str, source_id: str, exact_evidence_span: str, start: { type: 'integer', minimum: 0 },
  end: { type: 'integer', minimum: 1 }, normalized_statement: str, semantic_type: str,
  certainty: confidence, time_reference: nullable(str), entity_refs: strings,
})
export const nodeSchema = object({
  node_id: str, title: str, level: enumeration(...levels), goal: nullable(str),
  done_condition: nullable(str), status: str, time_window: nullable(str), evidence_refs: refs, confidence,
})
export const relationSchema = object({
  relation_id: str, from_id: str, to_id: str, type: enumeration(...pairwise, ...structural),
  evidence_refs: refs, rationale: str, confidence,
})
export const claimSchema = object({
  claim_id: str, verdict: enumeration('SUPPORTED', 'PARTIALLY_SUPPORTED', 'UNSUPPORTED'),
  critical: { type: 'boolean' }, evidence_refs: refs, rationale: str,
})
export const reviewSchema = object({
  run_id: str, model: str, reviewed_at: date, annotation_digest: digest,
  context: { const: 'separate-run' }, claims: list(claimSchema, 1),
  checks: object(Object.fromEntries(['invented_goals', 'invented_deadlines', 'invented_dependencies', 'over_merging', 'over_splitting', 'forced_ontology'].map(k => [k, { const: true }]))),
})
export const episodeSchema = {
  $schema: 'http://json-schema.org/draft-07/schema#',
  ...object({
    schema_version: { const: 'gold-candidate-episode/v1' }, episode_id: { type: 'string', pattern: '^GC-[0-9]{6}$' },
    dataset_id: str, project_id: str, ecosystem: str, language: enumeration('en', 'ja', 'mixed'),
    difficulty: enumeration('easy', 'medium', 'hard', 'adversarial'),
    work_type: enumeration('bug', 'feature', 'architecture', 'documentation', 'testing', 'infrastructure', 'release', 'performance', 'migration', 'design', 'research'),
    split: enumeration('TRAIN-CANDIDATE', 'DEV-CANDIDATE', 'TEST-CANDIDATE'),
    provenance: object({ source_family: enumeration(...families), dataset_version: str, source_urls: refs, license: str, retrieved_at: date, raw_hashes: refs }),
    sources: list(sourceSchema, 1), semantic_atoms: list(atomSchema, 1), work_nodes: list(nodeSchema, 1), relations: list(relationSchema),
    evidence_map: list(object({ claim_id: str, atom_ids: refs }), 1),
    timeline: list(object({ source_id: str, timestamp: date, event: str })),
    ambiguities: list(object({ kind: enumeration('UNCERTAIN', 'UNKNOWN_LEVEL', 'UNKNOWN_RELATION', 'MISSING_CONTEXT', 'UNRESOLVED_NODE_BOUNDARY', 'ONTOLOGY_MISMATCH'), description: str, evidence_refs: refs })),
    negative_candidates: list(object({ from_id: str, to_id: str, rationale: str, evidence_refs: refs })),
    hard_cases: { type: 'array', uniqueItems: true, items: { type: 'string', pattern: '^[A-Z][A-Z0-9_]*$' } },
    annotation: object({ proposed_by: { const: 'gpt' }, model: str, run_id: str, created_at: date,
      independent_review: reviewSchema, human_verified: { const: false }, candidate_status: { const: 'PENDING' }, confidence, rationale: str }),
  }),
}
export const manifestSchema = object({
  dataset_id: str, name: str, source_family: enumeration(...families), source_url: { type: 'string', format: 'uri' },
  version: str, retrieved_at: date, license: str, license_evidence_url: { type: 'string', format: 'uri' },
  redistribution_policy: enumeration('open-with-attribution', 'references-and-derived-only'),
  attribution_required: { type: 'boolean' }, attribution: str, contains_personal_data: { type: 'boolean' },
  anonymized: { const: true }, source_types: refs, language: refs, known_limitations: strings,
  checksum: digest, local_path: str, notes: str, status: { const: 'ACQUIRED' },
})
export const candidateSchema = object({
  schema_version: { const: 'episode-candidate/v1' }, candidate_id: str, dataset_id: str, project_id: str,
  ecosystem: str, split: episodeSchema.properties.split, sources: list(sourceSchema, 1),
  selection_rationale: str, status: enumeration('RAW', 'SILVER', 'ANNOTATION_PENDING', 'CRITIC_PENDING'),
})
